console.log('Observed verified observations:'); observations.forEach((o) => console.log('  ' + o));

// Open frames on a timeout row, then check 360 px.
await evaluate(`[...document.querySelectorAll('#log-body button')][2].click()`);
await send('Emulation.setDeviceMetricsOverride', { width: 360, height: 800, deviceScaleFactor: 1, mobile: true });
await sleep(400);
const widths = await evaluate(`({ doc: document.documentElement.scrollWidth, body: document.body.scrollWidth, region: document.querySelector('.table-scroll').scrollWidth, regionClient: document.querySelector('.table-scroll').clientWidth, openFrames: [...document.querySelectorAll('#log-body .frames-row')].filter(r => !r.hidden).length })`);
check(widths.doc <= 360 && widths.body <= 360, 'no document overflow at 360 px', JSON.stringify(widths));
check(widths.region > widths.regionClient && widths.openFrames === 1, 'log scrolls inside its region at 360 px with one frames row open');
await sleep(200);
check(problems.length === 0, 'no console errors, warnings, exceptions or HTTP >= 400', problems.join(' || '));

console.log(`SUMMARY ${results.filter((r) => r.ok).length}/${results.length} passed`);
ws.close();
chrome.kill();
process.exit(results.every((r) => r.ok) ? 0 : 1);
